    import sys
    input = sys.stdin.read
    data = input().split()
    N, H, W = int(data[0]), int(data[1]), int(data[2])
    tiles = [(int(data[i]), int(data[i+1])) for i in range(3, 2*N+3, 2)]

    def can_cover(H, W, tiles):
        if H * W < sum(a * b for a, b in tiles):
            return False
        if H * W > sum(a * b for a, b in tiles):
            return True
        for a, b in tiles:
            if a > H and b > W:
                return False
        return True

    if can_cover(H, W, tiles):
        print("ใช่")
    else:
        print("ไม่")

