def process_queries():
    import sys
    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    A = list(map(int, data[1:N+1]))
    Q = int(data[N+1])
    queries = data[N+2:]

    index_map = {val: idx for idx, val in enumerate(A)}

    for i in range(0, len(queries), 3):
        query_type = int(queries[i])
        x = int(queries[i+1])
        if query_type == 1:
            y = int(queries[i+2])
            idx = index_map[x]
            A.insert(idx + 1, y)
            for key in index_map:
                if index_map[key] > idx:
                    index_map[key] += 1
            index_map[y] = idx + 1
        else:
            idx = index_map[x]
            del A[idx]
            for key in index_map:
                if index_map[key] > idx:
                    index_map[key] -= 1
            del index_map[x]

    print(' '.join(map(str, A)))

process_queries()

