def find_farthest_points():
    import math
    N = int(input())
    points = []
    for _ in range(N):
        x, y = map(int, input().split())
        points.append((x, y))

    for i in range(N):
        max_dist = -1
        farthest_id = -1
        for j in range(N):
            if i != j:
                dist = math.sqrt((points[i][0] - points[j][0])**2 + (points[i][1] - points[j][1])**2)
                if dist > max_dist or (dist == max_dist and j < farthest_id):
                    max_dist = dist
                    farthest_id = j
        print(farthest_id + 1)

