class Solution:
    def minOperationsToMakeMedianK(self, nums: List[int], k: int) -> int:
        nums.sort()
        n = len(nums)
        mid = n // 2
        if n % 2 == 0:
            median = max(nums[mid - 1], nums[mid])
        else:
            median = nums[mid]
        if median == k:
            return 0
        if median < k:
            return sum(k - num for num in nums[mid:])
        else:
            return sum(num - k for num in nums[:mid + 1])
