class Solution:
    def unmarkedSumArray(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        marked = [False] * len(nums)
        sorted_nums = sorted((num, i) for i, num in enumerate(nums))
        result = []
        total_sum = sum(nums)

        for index, k in queries:
            if not marked[index]:
                marked[index] = True
                total_sum -= nums[index]

