class Solution:
    def sumOfPowers(self, nums: List[int], k: int) -> int:
        MOD = 10**9 + 7
        nums.sort()
        n = len(nums)
        left = [0] * n
        right = [0] * n
        stack = []
        for i in range(n):
            while stack and nums[stack[-1]] < nums[i]:
                stack.pop()
            if stack:
                left[i] = i - stack[-1] - 1
            else:
                left[i] = i
            stack.append(i)
        stack.clear()
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] > nums[i]:
                stack.pop()
            if stack:
                right[i] = stack[-1] - i - 1
            else:
                right[i] = n - 1 - i
            stack.append(i)
        result = 0
        for i in range(n):
            result += nums[i] * (left[i] * (n - i - right[i] - 1) - right[i] * (i - left[i] - 1))
            result %= MOD
        return result
```

