    def minimumSubstringsInPartition(self, s: str) -> int:
        def is_balanced(sub):
            if not sub:
                return False
            char_count = {}
            for char in sub:
                if char in char_count:
                    char_count[char] += 1
                else:
                    char_count[char] = 1
            return len(set(char_count.values())) == 1

        def min_substrings(s, start, memo):
            if start == len(s):
                return 0
            if start in memo:
                return memo[start]
            min_count = float('inf')
            for end in range(start + 1, len(s) + 1):
                if is_balanced(s[start:end]):
                    min_count = min(min_count, 1 + min_substrings(s, end, memo))
            memo[start] = min_count
            return min_count

        return min_substrings(s, 0, {})
